DROP TABLE IF EXISTS `refund_bank_fees`;
CREATE TABLE `refund_bank_fees` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `invoice_refund_id` int(11) NOT NULL,
  `fee_amount` decimal(15,2) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_refund_bank_fees_refund` (`invoice_refund_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `signature_library`;
CREATE TABLE `signature_library` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `signature_name` varchar(191) NOT NULL COMMENT 'Final name, pattern: [name]_[year]',
  `signature_date` date NOT NULL,
  `company_name` varchar(191) NOT NULL DEFAULT '',
  `origin` varchar(191) NOT NULL DEFAULT '',
  `is_main` tinyint(1) unsigned NOT NULL DEFAULT 0,
  `original_filename` varchar(255) NOT NULL,
  `stored_filename` varchar(255) NOT NULL COMMENT 'Actual filename on disk',
  `file_path` varchar(255) NOT NULL COMMENT 'Relative path under storage/document_tools/signatures/',
  `file_ext` varchar(20) NOT NULL,
  `file_size` int(10) unsigned NOT NULL DEFAULT 0,
  `uploaded_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_signature_date` (`signature_date`),
  KEY `idx_company_origin` (`company_name`,`origin`),
  KEY `idx_is_main` (`is_main`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

DROP TABLE IF EXISTS `transaction_disbursements`;
CREATE TABLE `transaction_disbursements` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `transaction_id` int(10) unsigned NOT NULL,
  `activity_id` int(10) unsigned NOT NULL,
  `category_id` int(10) unsigned NOT NULL,
  `cashflow_type` enum('inflow','outflow','in-out') NOT NULL,
  `transaction_purpose` varchar(255) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_txn` (`transaction_id`),
  KEY `idx_activity` (`activity_id`),
  KEY `idx_td_category` (`category_id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

